<?php require 'config.php';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['cake_id'];$q=max(1,(int)$_POST['quantity']);$size=$_POST['size']??'1 kg';$msg=trim($_POST['message_text']??'');$s=$pdo->prepare('SELECT id,stock FROM cakes WHERE id=? AND active=1');$s->execute([$id]);$c=$s->fetch();if(!$c||$q>$c['stock'])exit('Cake unavailable or quantity exceeds stock');$_SESSION['cart'][$id]=['quantity'=>$q,'size'=>$size,'message_text'=>$msg];header('Location: cart.php');exit;}if(isset($_GET['remove'])){unset($_SESSION['cart'][(int)$_GET['remove']]);header('Location: cart.php');exit;}$items=[];$total=0;if(!empty($_SESSION['cart'])){$ids=array_keys($_SESSION['cart']);$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM cakes WHERE id IN ($marks)");$s->execute($ids);foreach($s->fetchAll() as $c){$x=$_SESSION['cart'][$c['id']];$c['quantity']=$x['quantity'];$c['size']=$x['size'];$c['message_text']=$x['message_text'];$total+=$c['price']*$c['quantity'];$items[]=$c;}}?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>Shopping cart</h1><?php foreach($items as $c):?><p><b><?=h($c['name'])?></b> · <?=h($c['size'])?> · Qty <?=h($c['quantity'])?> · <?=money($c['price']*$c['quantity'])?> <a href="cart.php?remove=<?=$c['id']?>">Remove</a><br><span class="muted"><?=h($c['message_text'])?></span></p><?php endforeach;?><h2>Total: <?=money($total)?></h2><?php if($items):?><a class="btn" href="checkout.php">Place order</a><?php else:?><p>Your cart is empty.</p><?php endif;?></div><a href="cakes.php">Continue shopping</a></div></body></html>